const failed = (
<Alert type="error" dismissible onDismiss={() => console.log('dismissed')}>
Could not save your changes.
</Alert>
);

const summary = (
<Card title="Invoice #1042" elevation={2} interactive>
Due in 14 days.
</Card>
);

const consent = (
<Checkbox label="Email me receipts" required onCheckedChange={(on) => console.log(on)} />
);

const currency = (
<Combobox
label="Currency"
options={[
{ value: 'chf', label: 'Swiss franc' },
{ value: 'eur', label: 'Euro', disabled: true },
]}
onValueChange={(value) => console.log(value)}
/>
);

const remote = (
<Combobox
label="Customer"
filterable
noResultsMessage="No customers match that name"
loadOptions={async (query) => [{ value: query, label: query }]}
onInputValueChange={(text) => console.log(text)}
/>
);

const columns = [
{ id: 'name', header: 'Name', get: (row) => row.name, sortable: true },
{ id: 'due', header: 'Due', get: (row) => row.due, width: '8rem' },
];
const rows = [{ id: '1', name: 'Invoice #1042', due: '2026-08-14' }];
const table = <DataTable columns={columns} rows={rows} />;

const paged = (
<DataTable
columns={[]}
rows={[]}
selectionMode="multi"
density="compact"
pageSize={50}
page={2}
onPageChange={(next) => console.log(next)}
onSelectionChange={(ids) => console.log(ids.length)}
onSortChange={(change) => console.log(change.columnId, change.direction)}
/>
);

const empty = (
<DataTable columns={[]} rows={[]} emptyMessage="No invoices yet">
Toolbar content
</DataTable>
);

const confirm = (
<Dialog
title="Delete invoice?"
open
size="small"
dismissOnBackdrop={false}
onDismiss={(reason) => console.log(reason.reason)}
>
This cannot be undone.
</Dialog>
);

const editor = (
<Dialog title="Edit invoice" size="fullscreen" dismissOnEscape={false}>
Form goes here
</Dialog>
);

const signup = (
<Form
label="Sign up"
layout="stacked"
validateOn="blur"
initialValues={{ email: '' }}
onSubmit={(values) => console.log(values.email)}
>
Field components go here
</Form>
);

const busy = (
<Form label="Sign up" submitting onReset={() => console.log('reset')}>
Fields are disabled while submitting.
</Form>
);

const tabs = (
<Tabs selectedIndex={1} onSelectedIndexChange={(i) => console.log(i)}>
Panel content
</Tabs>
);

const email = (
<TextField
label="Email"
type="email"
required
hint="We only use this for receipts."
onValueChange={(next) => console.log(next)}
/>
);

const hint = (
<Tooltip content="Deletes the invoice permanently" placement="right" openDelay={400}>
Delete
</Tooltip>
);
